SELECT status, method, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN status = 'SUCCESS' THEN 1 END), 0), 2) AS amount_per_success, PERCENTILE_APPROX(amount, 0.95) AS amount_p95, SORT_ARRAY(COLLECT_SET(status)) AS status_list, RANK() OVER (PARTITION BY status ORDER BY PERCENTILE_APPROX(amount, 0.95) DESC) AS amount_p95_rank FROM payments GROUP BY status, method HAVING amount_p95 >= 0;
